// @FIGURE_CODE_BEGIN
var state = { logL: -3.6, zoom: false };
var FULL = [-5.6, -0.35], ZOOMD = [-3.78, -2.42];
var B1 = -3.602, B2 = -2.602; // 2.5e-4 cm and 2.5e-3 cm boundaries of organic IR

var frame = setPlotFrame({ xDomain: FULL.slice(), yDomain: [0, 10], margin: 26 });
var draw = frame.draw;
var cont = document.getElementById('container');

var SEGS = [
  { a: -5.6,  b: -4.95, c: '#b381c2', label: ['Ultraviolet'], tip: 'Ultraviolet: λ < 10⁻⁵ cm. Very high energy — electronic transitions.' },
  { a: -4.95, b: -4.55, c: '#d9a3cf', label: ['Visible'], tip: 'Visible: a narrow sliver of the spectrum.' },
  { a: -4.55, b: B1,    c: '#eec3d6', label: ['Near', 'infrared'], tip: 'Near infrared: 10⁻⁴ – 2.5×10⁻⁴ cm. Overtones, not routine structure work.' },
  { a: B1,    b: B2,    c: '#f3a9bd', label: ['Infrared'], tip: 'Infrared (organic IR window): 2.5–25 μm = 4000–400 cm⁻¹. Where vibrational spectra live.' },
  { a: B2,    b: -1.75, c: '#fae6ee', label: ['Far', 'infrared'], tip: 'Far infrared: 25 μm – 10⁻² cm. Low-energy vibrations and rotations.' },
  { a: -1.75, b: -0.35, c: '#d9dcbf', label: ['Microwaves'], tip: 'Microwaves: λ up to 10⁻¹ cm. Rotational transitions, very low energy.' }
];

var SUP = { '-': '⁻', '0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹' };
function sup(n) { return String(n).split('').map(function (d) { return SUP[d] || d; }).join(''); }
function sci(log) { var e = Math.floor(log + 1e-9); var m = Math.pow(10, log - e); return m.toFixed(1) + '×10' + sup(e); }
function fmtNum(v) { if (v >= 1000) return String(Math.round(v)); if (v >= 100) return v.toFixed(0); if (v >= 1) return v.toFixed(1); return v.toPrecision(2); }

function render() {
  draw.clear();
  var f = frame, W = f.width, H = f.height;
  var FS = Math.max(10, Math.min(W, H) * 0.026);
  var yT = plotY(8.7), yB = plotY(5.5);
  var d0 = f.xDomain[0], d1 = f.xDomain[1];
  var x0 = plotX(d0), x1 = plotX(d1);

  // ── segments ──────────────────────────────────────────────────────────
  SEGS.forEach(function (s) {
    if (s.b <= d0 || s.a >= d1) return;
    var xa = plotX(Math.max(s.a, d0)), xb = plotX(Math.min(s.b, d1));
    var r = draw.rect(xb - xa, yB - yT).move(xa, yT)
      .fill(s.c).stroke({ color: '#777', width: 0.6 });
    r.css('cursor', 'pointer');
    r.on('mousemove', function (e) { showTooltip(s.tip, e); })
     .on('mouseleave', function () { hideTooltip(); })
     .on('click', function () { showPopup(s.label.join(' '), s.tip + '  λ and energy always move in opposite directions along this strip.'); });
    // label
    var cx = (xa + xb) / 2;
    if (xb - xa > FS * 2.2) {
      var tx = draw.text(function (add) {
        s.label.forEach(function (p, i) { if (i === 0) add.tspan(p); else add.tspan(p).newLine(); });
      }).font({ size: FS, family: 'sans-serif', anchor: 'middle' }).fill('#222');
      tx.center(cx, (yT + yB) / 2);
    }
  });

  // ── ragged torn edges (full view) ─────────────────────────────────────
  if (!state.zoom) {
    [x0, x1].forEach(function (xe, k) {
      var p = 'M ' + xe + ' ' + yT, yy = yT, dir = k ? -1 : 1, n = 0;
      while (yy < yB) { yy = Math.min(yB, yy + 7); p += ' q ' + (dir * 5) + ' 3.5 0 7'; dir = -dir; n++; }
      draw.path(p).fill('none').stroke({ color: '#777', width: 1 });
    });
  }

  // ── highlight the segment under the marker ────────────────────────────
  var mx = plotX(state.logL);
  SEGS.forEach(function (s) {
    if (state.logL >= s.a && state.logL < s.b && s.b > d0 && s.a < d1) {
      var xa = plotX(Math.max(s.a, d0)), xb = plotX(Math.min(s.b, d1));
      draw.rect(xb - xa, yB - yT).move(xa, yT).fill('#ffffff').opacity(0.18)
        .stroke({ color: '#333', width: 1.4 });
    }
  });

  // ── wavelength axis ticks ─────────────────────────────────────────────
  for (var k = -5; k <= -1; k++) {
    if (k < d0 + 0.01 || k > d1 - 0.01) continue;
    var tx2 = plotX(k);
    draw.line(tx2, yB, tx2, yB + 8).stroke({ color: '#333', width: 1 });
    draw.text('10' + sup(k)).font({ size: FS, family: 'sans-serif', anchor: 'middle' })
      .center(tx2, yB + 8 + FS * 0.9);
  }
  if (!state.zoom) {
    draw.text(function (add) { add.tspan('λ'); add.tspan('(cm)').newLine(); })
      .font({ size: FS, family: 'sans-serif', anchor: 'start' })
      .move(x0, yB + 8 + FS * 1.4);
  }

  // ── energy gradient arrow (points LEFT, opposite the λ axis) ──────────
  var ay = yT - FS * 3.2, ah = FS * 1.0, head = ah * 1.7;
  var axL = plotX(d0 + (d1 - d0) * 0.04), axR = plotX(d1 - (d1 - d0) * 0.08);
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#e8562a'); add.stop(1, '#f6e79b');
  }).from(0, 0).to(1, 0);
  draw.polygon([
    [axL, ay], [axL + head, ay - head * 0.85], [axL + head, ay - ah],
    [axR, ay - ah], [axR, ay + ah], [axL + head, ay + ah], [axL + head, ay + head * 0.85]
  ].map(function (p) { return p.join(','); }).join(' ')).fill(grad).stroke({ color: '#c94a22', width: 0.8 });
  draw.text('Energy').font({ size: FS * 1.1, family: 'sans-serif', anchor: 'middle', weight: 'bold' })
    .fill('#3a1c08').center((axL + head + axR) / 2, ay);

  // ── leader-line annotations for the organic IR window ─────────────────
  var xb1 = plotX(B1), xb2 = plotX(B2);
  if (!state.zoom) {
    var ayTxt = yB + FS * 3.2;
    // left boundary: λ = 2.5×10⁻⁴ cm = 2.5 μm, ν̃ = 4000 cm⁻¹
    draw.line(xb1, yB, xb1, ayTxt - FS * 0.4).stroke({ color: '#555', width: 1 });
    draw.line(xb1, ayTxt - FS * 0.4, xb1 - FS * 3.2, ayTxt - FS * 0.4).stroke({ color: '#555', width: 1 });
    draw.text(function (add) {
      add.tspan('λ = 2.5 × 10⁻⁴ cm'); add.tspan('= 2.5 μm').newLine(); add.tspan('ν̃ = 4000 cm⁻¹').newLine();
    }).font({ size: FS * 0.92, family: 'sans-serif', anchor: 'end' }).fill('#111')
      .move(0, 0).attr({ x: xb1 - FS * 3.3, y: ayTxt - FS * 1.1 });
    // right boundary
    draw.line(xb2, yB, xb2, ayTxt - FS * 0.4).stroke({ color: '#555', width: 1 });
    draw.line(xb2, ayTxt - FS * 0.4, xb2 + FS * 3.2, ayTxt - FS * 0.4).stroke({ color: '#555', width: 1 });
    draw.text(function (add) {
      add.tspan('λ = 2.5 × 10⁻³ cm'); add.tspan('= 25 μm').newLine(); add.tspan('ν̃ = 400 cm⁻¹').newLine();
    }).font({ size: FS * 0.92, family: 'sans-serif', anchor: 'start' }).fill('#111')
      .attr({ x: xb2 + FS * 3.4, y: ayTxt - FS * 1.1 });
  } else {
    // zoomed: boundary labels retained at the ends
    draw.text(function (add) { add.tspan('ν̃ = 4000 cm⁻¹'); add.tspan('(2.5 μm)').newLine(); })
      .font({ size: FS * 0.9, family: 'sans-serif', anchor: 'start' }).fill('#111')
      .attr({ x: x0 + 4, y: yB + FS * 2.6 });
    draw.text(function (add) { add.tspan('ν̃ = 400 cm⁻¹'); add.tspan('(25 μm)').newLine(); })
      .font({ size: FS * 0.9, family: 'sans-serif', anchor: 'end' }).fill('#111')
      .attr({ x: x1 - 4, y: yB + FS * 2.6 });
    draw.text('The organic IR window — one narrow slice of the whole infrared region')
      .font({ size: FS * 0.85, family: 'sans-serif', anchor: 'middle', style: 'italic' }).fill('#555')
      .center((x0 + x1) / 2, yB + FS * 5.2);
  }

  // ── draggable wavelength marker ───────────────────────────────────────
  var lam = Math.pow(10, state.logL);
  var um = lam * 1e4, wn = 1 / lam, erel = wn / 4000;
  var readout = 'λ = ' + sci(state.logL) + ' cm = ' + fmtNum(um) + ' μm    ν̃ = ' + fmtNum(wn) + ' cm⁻¹    E(rel) = ' + erel.toFixed(2);
