Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Wavelength λ (log cm): <output id="wavelengthSliderVal">-3.60</output><input id="wavelengthSliderInput" type="range" min="-5.6" max="-0.35" step="0.05" value="-3.6" oninput="document.getElementById('wavelengthSliderVal').value=(+this.value).toFixed(2);update_wavelengthSlider(+this.value)"></label>
