// @FIGURE_CODE_BEGIN
var state = { logL: -3.6, zoom: false };
var FULL = [-5.6, -0.35], ZOOMD = [-3.78, -2.42];
var B1 = -3.602, B2 = -2.602; // boundaries of the organic IR window

var frame = setPlotFrame({ xDomain: FULL.slice(), yDomain: [0, 10], margin: 30 });
var draw = frame.draw;
var cont = document.getElementById('container');

var SEGS = [
  { a: -5.6,  b: -4.95, c: '#b381c2', label: ['Ultraviolet'], tip: 'Ultraviolet: λ < 10⁻⁵ cm. Very high energy — electronic transitions.' },
  { a: -4.95, b: -4.55, c: '#d9a3cf', label: ['Visible'], tip: 'Visible: a narrow sliver of the spectrum between ultraviolet and near infrared.' },
  { a: -4.55, b: B1,    c: '#eec3d6', label: ['Near', 'infrared'], tip: 'Near infrared: 10⁻⁴ – 2.5×10⁻⁴ cm. Overtones, not routine structure work.' },
  { a: B1,    b: B2,    c: '#f3a9bd', label: ['Infrared'], tip: 'Infrared (organic IR window): 2.5–25 μm = 4000–400 cm⁻¹. Where vibrational spectra live.' },
  { a: B2,    b: -1.75, c: '#fae6ee', label: ['Far', 'infrared'], tip: 'Far infrared: 25 μm – 10⁻² cm. Low-energy vibrations and rotations.' },
  { a: -1.75, b: -0.35, c: '#d9dcbf', label: ['Microwaves'], tip: 'Microwaves: λ up to 10⁻¹ cm. Rotational transitions, very low energy.' }
];

var SUP = { '-': '⁻', '0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹' };
function sup(n) { return String(n).split('').map(function (d) { return SUP[d] || d; }).join(''); }
function sci(log) { var e = Math.floor(log + 1e-9); var m = Math.pow(10, log - e); return m.toFixed(1) + '×10' + sup(e); }
function fmtNum(v) { if (v >= 1000) return String(Math.round(v)); if (v >= 100) return v.toFixed(0); if (v >= 1) return v.toFixed(1); return v.toPrecision(2); }

function render() {
  draw.clear();
  var f = frame, W = f.width, H = f.height;
  var FS = Math.max(9, Math.min(W, H) * 0.026);
  var yT = plotY(8.4), yB = plotY(5.4);
  var d0 = f.xDomain[0], d1 = f.xDomain[1];
  var x0 = plotX(d0), x1 = plotX(d1);

  // ── segments ──────────────────────────────────────────────────────────
  SEGS.forEach(function (s) {
    if (s.b <= d0 || s.a >= d1) return;
    var xa = plotX(Math.max(s.a, d0)), xb = plotX(Math.min(s.b, d1));
    var r = draw.rect(xb - xa, yB - yT).move(xa, yT)
      .fill(s.c).stroke({ color: '#777', width: 0.6 });
    r.css('cursor', 'pointer');
    r.on('mousemove', function (e) { showTooltip(s.tip, e); })
     .on('mouseleave', function () { hideTooltip(); })
     .on('click', function () { showPopup(s.label.join(' '), s.tip + '  λ and energy always move in opposite directions along this strip.'); });
    // label: need room for the longest word; shrink font for narrow segments
    var cx = (xa + xb) / 2, segW = xb - xa;
    var longest = Math.max.apply(null, s.label.map(function (p) { return p.length; }));
    var size = Math.min(FS, (segW * 0.9) / (longest * 0.52));
    if (size >= 5) {
      var tx = draw.text(function (add) {
        s.label.forEach(function (p, i) { if (i === 0) add.tspan(p); else add.tspan(p).newLine(); });
      }).font({ size: size, family: 'sans-serif', anchor: 'middle' }).fill('#222');
      tx.center(cx, (yT + yB) / 2);
    }
  });

  // ── ragged torn edges (full view) ─────────────────────────────────────
  if (!state.zoom) {
    [x0, x1].forEach(function (xe, k) {
      var p = 'M ' + xe + ' ' + yT, yy = yT, dir = k ? -1 : 1;
      while (yy < yB) { yy = Math.min(yB, yy + 7); p += ' q ' + (dir * 5) + ' 3.5 0 7'; dir = -dir; }
      draw.path(p).fill('none').stroke({ color: '#777', width: 1 });
    });
  }

  // ── highlight the segment under the marker ────────────────────────────
  var mx = plotX(state.logL);
  SEGS.forEach(function (s) {
    if (state.logL >= s.a && state.logL < s.b && s.b > d0 && s.a < d1) {
      var xa = plotX(Math.max(s.a, d0)), xb = plotX(Math.min(s.b, d1));
      draw.rect(xb - xa, yB - yT).move(xa, yT).fill('#ffffff').opacity(0.18)
        .stroke({ color: '#333', width: 1.4 });
    }
  });

  // ── wavelength axis ticks ─────────────────────────────────────────────
  var tickLblY = yB + 8 + FS * 0.85;
  for (var k = -5; k <= -1; k++) {
    if (k < d0 + 0.01 || k > d1 - 0.01) continue;
    var tx2 = plotX(k);
    draw.line(tx2, yB, tx2, yB + 8).stroke({ color: '#333', width: 1 });
    draw.text('10' + sup(k)).font({ size: FS, family: 'sans-serif', anchor: 'middle' })
      .center(tx2, tickLblY);
  }
  if (!state.zoom) {
    draw.text(function (add) { add.tspan('λ'); add.tspan('(cm)').newLine(); })
      .font({ size: FS, family: 'sans-serif', anchor: 'start' })
      .move(x0, tickLblY + FS * 0.9);
  }

  // ── energy gradient arrow (points LEFT, opposite the λ axis) ──────────
  var ay = yT - FS * 3.6, ah = FS * 1.0, head = ah * 1.7;
  var axL = plotX(d0 + (d1 - d0) * 0.04), axR = plotX(d1 - (d1 - d0) * 0.08);
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#e8562a'); add.stop(1, '#f6e79b');
  }).from(0, 0).to(1, 0);
  draw.polygon([
    [axL, ay], [axL + head, ay - head * 0.85], [axL + head, ay - ah],
    [axR, ay - ah], [axR, ay + ah], [axL + head, ay + ah], [axL + head, ay + head * 0.85]
  ].map(function (p) { return p.join(','); }).join(' ')).fill(grad).stroke({ color: '#c94a22', width: 0.8 });
  draw.text('Energy').font({ size: FS * 1.1, family: 'sans-serif', anchor: 'middle', weight: 'bold' })
    .fill('#3a1c08').center((axL + head + axR) / 2, ay);

  // ── leader-line annotations for the organic IR window ─────────────────
  // Text sits on its own row well BELOW the tick-label row (source two-row layout),
  // with short leader stubs that cannot reach the tick labels.
  var xb1 = plotX(B1), xb2 = plotX(B2);
  if (!state.zoom) {
    var rowTop = tickLblY + FS * 1.6;   // clear of 10⁻⁴ / 10⁻³ tick labels
    var stubTop = yB + 8, stubY = rowTop - FS * 0.2;
    var stubLen = FS * 2.6;
    // left boundary: λ = 2.5×10⁻⁴ cm = 2.5 μm, ν̃ = 4000 cm⁻¹
    draw.line(xb1, stubTop, xb1, stubY).stroke({ color: '#555', width: 1 });
    draw.line(xb1, stubY, xb1 - stubLen, stubY).stroke({ color: '#555', width: 1 });
    draw.text(function (add) {
      add.tspan('λ = 2.5 × 10⁻⁴ cm'); add.tspan('= 2.5 μm').newLine(); add.tspan('ν̃ = 4000 cm⁻¹').newLine();
    }).font({ size: FS * 0.9, family: 'sans-serif', anchor: 'end' }).fill('#111')
      .attr({ x: xb1 - stubLen - 4, y: rowTop - FS * 0.6 });
    // right boundary: λ = 2.5×10⁻³ cm = 25 μm, ν̃ = 400 cm⁻¹
    draw.line(xb2, stubTop, xb2, stubY).stroke({ color: '#555', width: 1 });
    draw.line(xb2, stubY, xb2 + stubLen, stubY).stroke({ color: '#555', width: 1 });
    draw.text(function (add) {
      add.tspan('λ = 2.5 × 10⁻³ cm'); add.tspan('= 25 μm').newLine(); add.tspan('ν̃ = 400 cm⁻¹').newLine();
    }).font({ size: FS * 0.9, family: 'sans-serif', anchor: 'start' }).fill('#111')
      .attr({ x: xb2 + stubLen + 4, y: rowTop - FS * 0.6 });
  } else {
    // zoomed: boundary labels retained at the ends
    draw.text(function (add) { add.tspan('ν̃ = 4000 cm⁻¹'); add.tspan('(2.5 μm)').newLine(); })
      .font({ size: FS * 0.9, family: 'sans-serif', anchor: 'start' }).fill('#111')
      .attr({ x: x0 + 4, y: tickLblY + FS * 1.4 });
    draw.text(function (add) { add.tspan('ν̃ = 400 cm⁻¹'); add.tspan('(25 μm)').newLine(); })
      .font({ size: FS * 0.9, family: 'sans-serif', anchor: 'end' }).fill('#111')
      .attr({ x: x1 - 4, y: tickLblY + FS * 1.4 });
    draw.text('The organic IR window — one narrow slice of the whole infrared region')
      .font({ size: FS * 0.85, family: 'sans-serif', anchor: 'middle', style: 'italic' }).fill('#555')
      .center((x0 + x1) / 2, tickLblY + FS * 3.8);
  }

  // ── draggable wavelength marker ───────────────────────────────────────
  var lam = Math.pow(10, state.logL);
  var um = lam * 1e4, wn = 1 / lam, erel = wn / 4000;
  var readout = 'λ = ' + sci(state.logL) + ' cm = ' + fmtNum(um) + ' μm   ν̃ = ' + fmtNum(wn) + ' cm⁻¹   E(rel) = ' + erel.toFixed(2);
  var half = readout.length * FS * 0.30;
  var cxr = Math.max(f.margin + half, Math.min(W - f.margin - half, mx));
  draw.text(readout).font({ size: FS * 0.95, family: 'sans-serif', anchor: 'middle', weight: 'bold' })
    .fill('#0a3d91').attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' })
    .center(cxr, yT - FS * 1.9);
  var mk = draw.group();
  mk.line(mx, yT - FS * 1.2, mx, yB + 2).stroke({ color: '#0a3d91', width: 1.6 });
  mk.polygon([[mx - FS * 0.45, yT - FS * 1.25], [mx + FS * 0.45, yT - FS * 1.25], [mx, yT - 1]]
    .map(function (p) { return p.join(','); }).join(' ')).fill('#0a3d91');
  mk.css('cursor', 'ew-resize');
  mk.on('mousemove', function (e) { showTooltip('Drag me: watch ν̃ and energy fall as λ grows', e); })
    .on('mouseleave', function () { hideTooltip(); });
  mk.on('pointerdown', function (e) {
    e.preventDefault();
    function mv(ev) {
      var r = cont.getBoundingClientRect();
      var cs = getComputedStyle(cont);
      // account for container padding and the draw's own offset so the marker
      // sits exactly under the cursor — no hardcoded pixel fudge
      var px = ev.clientX - r.left
        - (parseFloat(cs.paddingLeft) || 0)
        - (draw.node.offsetLeft || 0);
      var lg = f.xDomain[0] + (px - f.margin) / f.sx;
      lg = Math.max(f.xDomain[0], Math.min(f.xDomain[1], lg));
      document.getElementById('wavelengthSliderInput').value = lg;
      document.getElementById('wavelengthSliderVal').value = lg.toFixed(2);
      state.logL = lg; render();
    }
    function up() { window.removeEventListener('pointermove', mv); window.removeEventListener('pointerup', up); }
    window.addEventListener('pointermove', mv);
    window.addEventListener('pointerup', up);
  });
}

function update_wavelengthSlider(v) { state.logL = v; render(); }
function toggle_spectrumWindow(on) {
  state.zoom = on;
  frame = setPlotFrame({ xDomain: (on ? ZOOMD : FULL).slice(), yDomain: [0, 10], margin: 30, draw: draw });
  render();
}

// ── demo steps ──────────────────────────────────────────────────────────
var steps = [
  { n: 'The strip runs from ultraviolet (short wavelength) to microwaves (long wavelength), while the Energy arrow above points the opposite way — energy increases as wavelength decreases.', s: { log: -5, zoom: false } },
  { n: 'Slide the marker from left to right: the λ and μm values grow while the wavenumber and energy readouts shrink — the same physical position encodes both, always inversely.', s: { log: -1, zoom: false } },
  { n: 'Switching to the organic IR window zooms into the 2.5–25 μm span bounded by 4000 and 400 cm⁻¹ — the narrow midportion of infrared that organic chemists actually use for structure determination.', s: { log: -3.6, zoom: true } }
];
var curStep = 0;
function applyStep(i) {
  curStep = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[curStep];
  var cb = document.getElementById('spectrumWindowInput');
  cb.checked = st.s.zoom; toggle_spectrumWindow(st.s.zoom);
  document.getElementById('wavelengthSliderInput').value = st.s.log;
  document.getElementById('wavelengthSliderVal').value = st.s.log.toFixed(2);
  update_wavelengthSlider(st.s.log);
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = (curStep + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

document.addEventListener('fig-resize', function () { render(); });
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

